1	// Command darksafe is the 零信任身份与授权决策平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"os"
8	
9		"github.com/asdhoaiqqq/darksafe-access/darksafe"
10	)
11	
12	func main() {
13		command := "demo"
14		if len(os.Args) > 1 {
15			command = os.Args[1]
16		}
17		switch command {
18		case "demo":
19			runDemo()
20		case "version":
21			fmt.Println("darksafe 0.1.0")
22		case "plan":
23			runPlan(os.Args[2:])
24		case "help", "-h", "--help":
