		{`{` + base + `,"a\nb":1,"a\nb":2}`, "a\nb", `$["a\nb"]`},
		// leading digit / underscore rules
		{`{` + base + `,"1x":1,"1x":2}`, "1x", `$["1x"]`},
		{`{` + base + `,"_x1":1,"_x1":2}`, "_x1", "$._x1"},
		// non-ASCII letter is not an ASCII identifier char
		{`{` + base + `,"名":1,"名":2}`, "名", `$["名"]`},
		// dotted name inside array under unknown field
		{`{` + base + `,"items":[{"a.b":1,"a.b":2}]}`, "a.b", `$["items"][0]["a.b"]`},
	}
	for i, c := range cases {
		f, p := dupPath(t, c.body)
		if f != c.wantField {
			t.Errorf("case %d: field = %q, want %q (body %s)", i, f, c.wantField, c.body)
		}
		if p != c.wantPath {
			t.Errorf("case %d: path = %q, want %q (body %s)", i, p, c.wantPath, c.body)
		}
		// path must contain the object location, and extracting the bracketed
