package darksafe

import (
	"encoding/json"
	"strings"
	"testing"
)

func dupPath(t *testing.T, body string) (field, path string) {
	t.Helper()
	_, err := ParseReleaseInput([]byte(body))
	if err == nil {
		t.Fatalf("expected error for %s", body)
	}
	dme, ok := err.(*duplicateMemberError)
	if !ok {
		t.Fatalf("not a duplicateMemberError: %v", err)
	}
	return dme.field, dme.path
}

// extractBracketed pulls every ["..."] JSON-string segment out of a path and
// JSON-decodes it, proving the location text restores real member names.
func extractBracketed(t *testing.T, p string) []string {
	t.Helper()
	var out []string
	rest := p
	for {
		open := strings.Index(rest, "[\"")
		if open < 0 {
			return out
		}
		j := open + 2
		for j < len(rest) {
			if rest[j] == '\\' {
				j += 2
				continue
			}
			if rest[j] == '"' && j+1 < len(rest) && rest[j+1] == ']' {
				break
			}
			j++
		}
		if j >= len(rest) {
			t.Fatalf("unterminated bracket segment in path %q", p)
		}
		var s string
		if err := json.Unmarshal([]byte(rest[open+1:j+1]), &s); err != nil {
			t.Fatalf("segment not legal JSON in %q: %v", p, err)
		}
		out = append(out, s)
		rest = rest[j+2:]
	}
}

func TestVerify_IssueScenarios(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`
	cases := []struct {
		body      string
		wantField string
		wantPath  string
		wantSegs  []string // decoded names that must appear in bracket segments
	}{
		// The core ambiguity: dup INSIDE a top-level "meta.info" object vs
		// dup inside meta.info nested object.
		{`{` + base + `,"meta.info":{"x":1,"x":2}}`, "x", `$["meta.info"]`, []string{"meta.info"}},
		{`{` + base + `,"meta":{"info":{"x":1,"x":2}}}`, "x", `$.meta.info`, nil},
		// Dup of the specially-named member itself: owning object is root,
		// name reported separately.
		{`{` + base + `,"meta.info":1,"meta.info":2}`, "meta.info", `$`, nil},
		// Special names at deeper levels.
		{`{` + base + `,"meta":{"x.y":1,"x.y":2}}`, "x.y", `$["meta"]`[0:0] + `$.meta`, []string{}},
		{`{` + base + `,"zone[0]":{"x":1,"x":2}}`, "x", `$["zone[0]"]`, []string{"zone[0]"}},
		{`{` + base + `,"a":{"zone[0]":{"x":1,"x":2}}}`, "x", `$.a["zone[0]"]`, []string{"zone[0]"}},
		{`{` + base + `,"a.b":[{"x":1,"x":2}]}`, "x", `$["a.b"][0]`, []string{"a.b"}},
		{`{` + base + `,"a.b":{"c.d":{"x":1,"x":2}}}`, "x", `$["a.b"]["c.d"]`, []string{"a.b", "c.d"}},
		{`{` + base + `,"items":[{"a.b":{"x":1,"x":2}}]}`, "x", `$.items[0]["a.b"]`, []string{"a.b"}},
		// Existing simple-name locations unchanged.
		{`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[{"id":"x","tags":{"env":1,"env":2}}]}`, "env", "$.clusters[0].tags", nil},
		{`{` + base + `,"include":[{},{"env":1,"env":2}]}`, "env", "$.include[1]", nil},
		// Special member names that are themselves duplicated inside root:
		// owning object is root; the name is shown via field.
		{`{` + base + `,"":1,"":2}`, "", `$`, nil},
		{`{` + base + `,"a\"b":1,"a\"b":2}`, `a"b`, `$`, nil},
		{`{` + base + `,"a\\b":1,"a\\b":2}`, `a\b`, `$`, nil},
		{`{` + base + `,"a\nb":1,"a\nb":2}`, "a\nb", `$`, nil},
		// Same special names nested so they must appear IN the path.
		{`{` + base + `,"":{"x":1,"x":2}}`, "x", `$[""]`, []string{""}},
		{`{` + base + `,"a\"b":{"x":1,"x":2}}`, "x", `$["a\"b"]`, []string{`a"b`}},
		{`{` + base + `,"a\\b":{"x":1,"x":2}}`, "x", `$["a\\b"]`, []string{`a\b`}},
		{`{` + base + `,"a\nb":{"x":1,"x":2}}`, "x", `$["a\nb"]`, []string{"a\nb"}},
		// Leading digit -> bracket; underscore-start -> dot.
		{`{` + base + `,"1x":{"y":1,"y":2}}`, "y", `$["1x"]`, []string{"1x"}},
		{`{` + base + `,"_x1":{"y":1,"y":2}}`, "y", `$._x1`, nil},
		// Non-ASCII rune is not an ASCII identifier character.
		{`{` + base + `,"名":{"y":1,"y":2}}`, "y", `$["名"]`, []string{"名"}},
	}
	for i, c := range cases {
		f, p := dupPath(t, c.body)
		if f != c.wantField {
			t.Errorf("case %d: field = %q, want %q (body %s)", i, f, c.wantField, c.body)
		}
		if p != c.wantPath {
			t.Errorf("case %d: path = %q, want %q (body %s)", i, p, c.wantPath, c.body)
		}
		segs := extractBracketed(t, p)
		if len(segs) != len(c.wantSegs) {
			t.Errorf("case %d: decoded segments %v, want %v (path %s)", i, segs, c.wantSegs, p)
		} else {
			for k := range segs {
				if segs[k] != c.wantSegs[k] {
					t.Errorf("case %d: segment %d decoded = %q, want %q", i, k, segs[k], c.wantSegs[k])
				}
			}
		}
		// Every error message must name both the field and the object path.
		msg := (&duplicateMemberError{field: f, path: p}).Error()
		if !strings.Contains(msg, p) {
			t.Errorf("case %d: message %q omits path", i, msg)
		}
	}

	// Unicode-escape equivalence: literal vs \uXXXX spelling of the same name
	// must yield an identical path.
	escName := strings.ReplaceAll("meta.info", "m", `m`)
	direct := `{` + base + `,"meta.info":{"x":1,"x":2}}`
	escaped := `{` + base + `,"` + escName + `":{"x":1,"x":2}}`
	_, p1 := dupPath(t, direct)
	_, p2 := dupPath(t, escaped)
	if p1 != p2 {
		t.Errorf("escape spellings give different paths: %q vs %q", p1, p2)
	}

	// A legal config full of special extra names must still plan normally:
	// special names are ignored, never rejected, absent duplicates.
	valid := `{
		"app":"a","revision":"r","image":"i","batchSize":2,
		"clusters":[{"id":"c1"},{"id":"c2"}],
		"meta.info":{"x":1}, "zone[0]":{"y":2}, "":"empty",
		"weird\"na\tme":1, "meta":{"info":true}
	}`
	in, err := ParseReleaseInput([]byte(valid))
	if err != nil {
		t.Fatalf("special extra names must be accepted: %v", err)
	}
	plan, err := MakeReleasePlan(in)
	if err != nil {
		t.Fatalf("plan failed: %v", err)
	}
	if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "c1,c2" {
		t.Fatalf("unexpected plan: %+v", plan.Batches)
	}

	// Same decoded name in different objects is legal, even oddly spelled.
	ok := `{` + base + `,"meta.info":{"k":1},"other":{"meta.info":2}}`
	if _, err := ParseReleaseInput([]byte(ok)); err != nil {
		t.Fatalf("same name in different objects must be legal: %v", err)
	}
}
